// CSD_RATIONALE_BEGIN
// This strategy solves math word problems step-by-step, ensuring each arithmetic computation is enclosed in << >> delimiters.
// It uses a two-phase approach:
// 1. An unconstrained phase where tokens are generated freely until the first "<<" is encountered.
// 2. A constrained phase where tokens are generated under grammar constraints until the problem is solved.
// During the unconstrained phase, we penalize ">>" to prevent premature termination.
// During the constrained phase, we use ConfidenceGatedStep to ensure the model stays within the correct grammar path.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
    }
  } else {
    if parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      var next, wasConstrained := helpers.ConfidenceGatedStep(lm, parser, prompt, currentConstrained);
      generated := generated + [next];
      steps := steps + 1;
      if wasConstrained {
        currentConstrained := currentConstrained + [next];
        if Contains(next, ">>") { insideConstrained := false; }
      } else {
        insideConstrained := false;
      }
    }
  }
}
cost := helpers.cost;

